pragma solidity ^0.8.0;

import {Test} from "forge-std/Test.sol";
import {PENNY_BY_PENNY} from "../src/PENNY_BY_PENNY.sol";

contract InvMutTest is Test {
    uint256 internal constant VALUE_CAP = 1000000000000000000000000000000;
    PENNY_BY_PENNY c;

    function setUp() public {
        c = new PENNY_BY_PENNY();
    }

    function _run(uint256 x) internal {
        uint256 beforeMinSum;
        try c.MinSum() returns (uint256 __r) { beforeMinSum = __r; } catch { return; }
        try c.Initialized() {} catch { return; }
        uint256 afterMinSum;
        try c.MinSum() returns (uint256 __r) { afterMinSum = __r; } catch { return; }
        assertTrue(afterMinSum == beforeMinSum);
    }

    function testFuzz_run(uint256 x) public {
        _run(x);
    }

    receive() external payable {}
}
